	PERF_ADJ_SALES_PY_BYTD_CNT,
	PERF_ADJ_SALES_PY_SWDAY_CNT,
	PERF_ADJ_SALES_PY_SWDAY_BYTD_CNT,
	PERF_ADJ_SALES_QTY,
	PERF_ADJ_SALES_BYTD_QTY,
	AGG_PERF_ADJ_SALES_QTY,
	PERF_ADJ_SALES_PY_QTY,
	PERF_ADJ_SALES_PY_BYTD_QTY,
