	PERF_ADJ_RETURN_BYTD_CNT,
	AGG_PERF_ADJ_RETURN_CNT,
	PERF_ADJ_RETURN_PY_CNT,
	PERF_ADJ_RETURN_PY_BYTD_CNT,
	PERF_ADJ_RETURN_PY_SWDAY_CNT,
	PERF_ADJ_RETURN_PY_SWDAY_BYTD_CNT,
	PERF_ADJ_RETURN_QTY,
	PERF_ADJ_RETURN_BYTD_QTY,
	AGG_PERF_ADJ_RETURN_QTY,
	PERF_ADJ_RETURN_PY_QTY,
	PERF_ADJ_RETURN_PY_BYTD_QTY,
	PERF_ADJ_RETURN_PY_SWDAY_QTY,
	PERF_ADJ_RETURN_PY_SWDAY_BYTD_QTY,
	UOM_CD,
	TURNOVER_NET_VAL,
	TURNOVER_BYTD_NET_VAL,
	AGG_TURNOVER_NET_VAL,
	TURNOVER_PY_NET_VAL,
	TURNOVER_PY_BYTD_NET_VAL,
	TURNOVER_PY_SWDAY_NET_VAL,
	TURNOVER_PY_SWDAY_BYTD_NET_VAL,
	PLAN_TURNOVER_NET_VAL,
	PLAN_TURNOVER_BYTD_NET_VAL,
	AGG_PLAN_TURNOVER_NET_VAL,
	PLAN_TURNOVER_PY_NET_VAL,
	PLAN_TURNOVER_PY_BYTD_NET_VAL,
	PLAN_TURNOVER_PY_SWDAY_NET_VAL,
	PLAN_TURNOVER_PY_SWDAY_BYTD_NET_VAL,
	CASH_REGISTER_SALES_NET_VAL,
	CASH_REGISTER_SALES_BYTD_NET_VAL,
	AGG_CASH_REGISTER_SALES_NET_VAL,
	CASH_REGISTER_SALES_PY_NET_VAL,
	CASH_REGISTER_SALES_PY_BYTD_NET_VAL,
	CASH_REGISTER_SALES_PY_SWDAY_NET_VAL,
	CASH_REGISTER_SALES_PY_SWDAY_BYTD_NET_VAL,
	CASH_REGISTER_RETURN_NET_VAL,
	CASH_REGISTER_RETURN_BYTD_NET_VAL,
	AGG_CASH_REGISTER_RETURN_NET_VAL,
	CASH_REGISTER_RETURN_PY_NET_VAL,
	CASH_REGISTER_RETURN_PY_BYTD_NET_VAL,
	CASH_REGISTER_RETURN_PY_SWDAY_NET_VAL,
	CASH_REGISTER_RETURN_PY_SWDAY_BYTD_NET_VAL,
	EOD_TURNOVER_NET_VAL,
	BOOKED_TURNOVER_NET_VAL,
	TURNOVER_GROSS_VAL,
	TURNOVER_BYTD_GROSS_VAL,
	AGG_TURNOVER_GROSS_VAL,
	TURNOVER_PY_GROSS_VAL,
	TURNOVER_PY_BYTD_GROSS_VAL,
	TURNOVER_PY_SWDAY_GROSS_VAL,
	TURNOVER_PY_SWDAY_BYTD_GROSS_VAL,
	CASH_REGISTER_SALES_GROSS_VAL,
	CASH_REGISTER_RETURN_GROSS_VAL,
	EOD_TURNOVER_GROSS_VAL,
	CURR_CD,
	RECEIPT_CNT,
	RECEIPT_BYTD_CNT,
	AGG_RECEIPT_CNT,
	RECEIPT_PY_CNT,
	RECEIPT_PY_BYTD_CNT,
	RECEIPT_PY_SWDAY_CNT,
	RECEIPT_PY_SWDAY_BYTD_CNT,
	CASH_REGISTER_RECEIPT_CNT,
	EOD_RECEIPT_CNT,
	BOOKED_RECEIPT_CNT,
	PLAN_RECEIPT_CNT,
	PLAN_RECEIPT_BYTD_CNT,
	AGG_PLAN_RECEIPT_CNT,
	PLAN_RECEIPT_PY_CNT,
	PLAN_RECEIPT_PY_BYTD_CNT,
	PLAN_RECEIPT_PY_SWDAY_CNT,
	PLAN_RECEIPT_PY_SWDAY_BYTD_CNT,
	DWH_CREATED_TMSP,
	DWH_UPDATED_TMSP,
	DWH_LOAD_ID,
	DWH_NODE_CD,
	FAILED_TURNOVER_BYTD_NET_VAL,
	FAILED_PLAN_TURNOVER_BYTD_NET_VAL,
	FAILED_TURNOVER_BYTD_GROSS_VAL,
	FAILED_RECEIPT_BYTD_CNT,
	FAILED_PLAN_RECEIPT_BYTD_CNT,
	FAILED_SALES_BYTD_CNT,
	FAILED_SALES_BYTD_QTY,
	FAILED_RETURN_BYTD_CNT,
	FAILED_RETURN_BYTD_QTY,
	FAILED_PERF_ADJ_SALES_BYTD_CNT,
	FAILED_PERF_ADJ_SALES_BYTD_QTY,
	FAILED_PERF_ADJ_RETURN_BYTD_CNT,
	FAILED_PERF_ADJ_RETURN_BYTD_QTY,
	FAILED_CASH_REGISTER_SALES_BYTD_NET_VAL,
	FAILED_CASH_REGISTER_RETURN_BYTD_NET_VAL,
	TOTAL
) COMMENT='Retail by store and day together with aggregated revenues (business year to date) to check, if BYTD columns are calculated correctly\ninput datasets:\ncore_dim.t_fact_retail_by_store_day\ncore_rel.t_cal_cum_business_year_to_date'
 as SELECT fact.bus_dt, dt.cal_dt, dt.bus_year, fact.int_org_sid, fact.int_org_type_cd, fact.country_org_cd, fact.sales_cnt, fact.sales_bytd_cnt, SUM(fact.sales_cnt) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_sales_cnt, fact.sales_py_cnt, fact.sales_py_bytd_cnt, fact.sales_py_swday_cnt, fact.sales_py_swday_bytd_cnt, fact.sales_qty, fact.sales_bytd_qty, SUM(fact.sales_qty) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_sales_qty, fact.sales_py_qty, fact.sales_py_bytd_qty, fact.sales_py_swday_qty, fact.sales_py_swday_bytd_qty, fact.return_cnt, fact.return_bytd_cnt, SUM(fact.return_cnt) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_return_cnt, fact.return_py_cnt, fact.return_py_bytd_cnt, fact.return_py_swday_cnt, fact.return_py_swday_bytd_cnt, fact.return_qty, fact.return_bytd_qty, SUM(fact.return_qty) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_return_qty, fact.return_py_qty, fact.return_py_bytd_qty, fact.return_py_swday_qty, fact.return_py_swday_bytd_qty, fact.perf_adj_sales_cnt, fact.perf_adj_sales_bytd_cnt, SUM(fact.perf_adj_sales_cnt) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_perf_adj_sales_cnt, fact.perf_adj_sales_py_cnt, fact.perf_adj_sales_py_bytd_cnt, fact.perf_adj_sales_py_swday_cnt, fact.perf_adj_sales_py_swday_bytd_cnt, fact.perf_adj_sales_qty, fact.perf_adj_sales_bytd_qty, SUM(fact.perf_adj_sales_qty) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_perf_adj_sales_qty, fact.perf_adj_sales_py_qty, fact.perf_adj_sales_py_bytd_qty, fact.perf_adj_sales_py_swday_qty, fact.perf_adj_sales_py_swday_bytd_qty, fact.perf_adj_return_cnt, fact.perf_adj_return_bytd_cnt, SUM(fact.perf_adj_return_cnt) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_perf_adj_return_cnt, fact.perf_adj_return_py_cnt, fact.perf_adj_return_py_bytd_cnt, fact.perf_adj_return_py_swday_cnt, fact.perf_adj_return_py_swday_bytd_cnt, fact.perf_adj_return_qty, fact.perf_adj_return_bytd_qty, SUM(fact.perf_adj_return_qty) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_perf_adj_return_qty, fact.perf_adj_return_py_qty, fact.perf_adj_return_py_bytd_qty, fact.perf_adj_return_py_swday_qty, fact.perf_adj_return_py_swday_bytd_qty, fact.uom_cd, fact.turnover_net_val, fact.turnover_bytd_net_val, SUM(fact.turnover_net_val) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_turnover_net_val, fact.turnover_py_net_val, fact.turnover_py_bytd_net_val, fact.turnover_py_swday_net_val, fact.turnover_py_swday_bytd_net_val, fact.plan_turnover_net_val, fact.plan_turnover_bytd_net_val, SUM(fact.plan_turnover_net_val) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_plan_turnover_net_val, fact.plan_turnover_py_net_val, fact.plan_turnover_py_bytd_net_val, fact.plan_turnover_py_swday_net_val, fact.plan_turnover_py_swday_bytd_net_val, fact.cash_register_sales_net_val, fact.cash_register_sales_bytd_net_val, SUM(fact.cash_register_sales_net_val) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_cash_register_sales_net_val, fact.cash_register_sales_py_net_val, fact.cash_register_sales_py_bytd_net_val, fact.cash_register_sales_py_swday_net_val, fact.cash_register_sales_py_swday_bytd_net_val, fact.cash_register_return_net_val, fact.cash_register_return_bytd_net_val, SUM(fact.cash_register_return_net_val) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_cash_register_return_net_val, fact.cash_register_return_py_net_val, fact.cash_register_return_py_bytd_net_val, fact.cash_register_return_py_swday_net_val, fact.cash_register_return_py_swday_bytd_net_val, fact.eod_turnover_net_val, fact.booked_turnover_net_val, fact.turnover_gross_val, fact.turnover_bytd_gross_val, Sum(fact.turnover_gross_val) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_turnover_gross_val, fact.turnover_py_gross_val, fact.turnover_py_bytd_gross_val, fact.turnover_py_swday_gross_val, fact.turnover_py_swday_bytd_gross_val, fact.cash_register_sales_gross_val, fact.cash_register_return_gross_val, fact.eod_turnover_gross_val, fact.curr_cd, fact.receipt_cnt, fact.receipt_bytd_cnt, SUM(fact.receipt_cnt) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_receipt_cnt, fact.receipt_py_cnt, fact.receipt_py_bytd_cnt, fact.receipt_py_swday_cnt, fact.receipt_py_swday_bytd_cnt, fact.cash_register_receipt_cnt, fact.eod_receipt_cnt, fact.booked_receipt_cnt, fact.plan_receipt_cnt, fact.plan_receipt_bytd_cnt, SUM(fact.plan_receipt_cnt) OVER (PARTITION BY fact.int_org_sid,dt.bus_year ORDER BY fact.bus_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS agg_plan_receipt_cnt, fact.plan_receipt_py_cnt, fact.plan_receipt_py_bytd_cnt, fact.plan_receipt_py_swday_cnt, fact.plan_receipt_py_swday_bytd_cnt, fact.dwh_created_tmsp, fact.dwh_updated_tmsp, fact.dwh_load_id, fact.dwh_node_cd, CASE WHEN ( COALESCE(fact.turnover_bytd_net_val, -1) != COALESCE(agg_turnover_net_val, -1) ) THEN 1 ELSE 0 END AS failed_turnover_bytd_net_val, CASE WHEN ( COALESCE(fact.plan_turnover_bytd_net_val, -1) != COALESCE(agg_plan_turnover_net_val, -1) ) THEN 1 ELSE 0 END AS failed_plan_turnover_bytd_net_val, CASE WHEN ( COALESCE(fact.turnover_bytd_gross_val, -1) != COALESCE(agg_turnover_gross_val, -1) ) THEN 1 ELSE 0 END AS failed_turnover_bytd_gross_val, CASE WHEN ( COALESCE(fact.receipt_bytd_cnt, -1) != COALESCE(agg_receipt_cnt, -1) ) THEN 1 ELSE 0 END AS failed_receipt_bytd_cnt, CASE WHEN ( COALESCE(fact.plan_receipt_bytd_cnt, -1) != COALESCE(agg_plan_receipt_cnt, -1) ) THEN 1 ELSE 0 END AS failed_plan_receipt_bytd_cnt, CASE WHEN ( COALESCE(fact.sales_bytd_cnt, -1) != COALESCE(agg_sales_cnt, -1) ) THEN 1 ELSE 0 END AS failed_sales_bytd_cnt, CASE WHEN ( COALESCE(fact.sales_bytd_qty, -1) != COALESCE(agg_sales_qty, -1) ) THEN 1 ELSE 0 END AS failed_sales_bytd_qty, CASE WHEN ( COALESCE(fact.return_bytd_cnt, -1) != COALESCE(agg_return_cnt, -1) ) THEN 1 ELSE 0 END AS failed_return_bytd_cnt, CASE WHEN ( COALESCE(fact.return_bytd_qty, -1) != COALESCE(agg_return_qty, -1) ) THEN 1 ELSE 0 END AS failed_return_bytd_qty, CASE WHEN ( COALESCE(fact.perf_adj_sales_bytd_cnt, -1) != COALESCE(agg_perf_adj_sales_cnt, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_sales_bytd_cnt, CASE WHEN ( COALESCE(fact.perf_adj_sales_bytd_qty, -1) != COALESCE(agg_perf_adj_sales_qty, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_sales_bytd_qty, CASE WHEN ( COALESCE(fact.perf_adj_return_bytd_cnt, -1) != COALESCE(agg_perf_adj_return_cnt, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_return_bytd_cnt, CASE WHEN ( COALESCE(fact.perf_adj_return_bytd_qty, -1) != COALESCE(agg_perf_adj_return_qty, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_return_bytd_qty, CASE WHEN ( COALESCE(fact.cash_register_sales_bytd_net_val, -1) != COALESCE(agg_cash_register_sales_net_val, -1) ) THEN 1 ELSE 0 END AS failed_cash_register_sales_bytd_net_val, CASE WHEN ( COALESCE(fact.cash_register_return_bytd_net_val, -1) != COALESCE(agg_cash_register_return_net_val, -1) ) THEN 1 ELSE 0 END AS failed_cash_register_return_bytd_net_val, 1 AS TOTAL FROM CORE_DIM.t_fact_retail_by_store_day AS fact JOIN CORE_DIM.t_dim_calendar_date AS dt ON fact.bus_dt = dt.cal_dt WHERE fact.bus_dt < current_date ORDER BY fact.int_org_sid, fact.bus_dt ASC;